new_posts = []
for idx, (cat, th, hk, fc) in enumerate(topics):
    item_id = next_id + idx
    if cat == "hot":
        new_posts.append({
            "id": item_id,
            "format": "hot",
            "caption": hk,
            "first_comment": fc
        })
    else:
        new_posts.append({
            "id": item_id,
            "format": "A",
            "category": cat,
            "theme": th,
            "hook": hk,
            "cta": "\n\n👉 এমন আরও AI ও টেক ট্রিকস পেতে ফলো করুন Mamun Hossain",
            "first_comment": fc
        })

queue.extend(new_posts)
content_file.write_text(json.dumps(queue, indent=2, ensure_ascii=False), encoding="utf-8")
print(f"Successfully added {len(new_posts)} items! Total queue depth: {len(queue)}")
